//! Where a FluxFrame Unit that fits no flux system is reported, checked
//! against the C library.
//!
//! `flux_badun_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/flux_badun_probe.c`. C's GetSystem takes an unset
//! System from a set Unit and raises AST__BADUN when no flux system's
//! default units convert to it. SetUnit stores the Unit and then reads the
//! System, clearing a set System the Unit does not fit, and the Title,
//! Label and Symbol defaults read the System (fluxframe.c GetSystem,
//! SetUnit, GetTitle, GetLabel, GetSymbol).

#[path = "flux_badun_oracle/cases.rs"]
mod cases;

use starlink_ast::error::{AstResult, ErrorCode};
use starlink_ast::frames::{FluxFrame, FluxSystem, Frame};

fn outcome(r: AstResult<String>) -> Result<String, String> {
    r.map_err(|e| match e.code() {
        ErrorCode::Badun => "Badun".to_string(),
        code => format!("{code:?}"),
    })
}

#[test]
fn bad_units_are_reported_as_in_the_c_library() {
    let mut failures = Vec::new();
    for &(system, unit, set, reads) in cases::CASES {
        let mut f = FluxFrame::with_spec_val(1.4e9, None);
        match system {
            "" => {}
            "System=FLXDN" => f.set_system(FluxSystem::FluxDen).unwrap(),
            other => panic!("no Rust set-up for {other}"),
        }
        let got_set = outcome(f.set_unit(1, unit).map(|()| String::new()));
        let got_reads: Vec<Result<String, String>> = cases::ATTRS
            .iter()
            .map(|&attr| {
                outcome(match attr {
                    "System" => f.system_string().map(|s| s.unwrap_or("").to_string()),
                    "Title" => f.title(),
                    "Label(1)" => f.label(1),
                    "Symbol(1)" => f.symbol(1),
                    "Unit(1)" => Frame::unit(&f, 1),
                    other => panic!("no Rust read for {other}"),
                })
            })
            .collect();
        let want_set = set.map(str::to_string).map_err(str::to_string);
        let want_reads: Vec<Result<String, String>> = reads
            .iter()
            .map(|r| r.map(str::to_string).map_err(str::to_string))
            .collect();
        if got_set != want_set || got_reads != want_reads {
            failures.push(format!(
                "[{system}] Unit={unit}: got {:?}, C gives {:?}",
                (got_set, got_reads),
                (want_set, want_reads)
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
